import{z as A,x as d,o as n,c as p,q as E,j as l,D as o,d as r,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"德摩根与对偶","description":"","frontmatter":{"title":"德摩根与对偶","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/de-morgan.md","filePath":"cs/de-morgan.md","lastUpdated":1791413859000}'),B={name:"cs/de-morgan.md"};function D(m,a,h,c,f,b){const t=d("Mermaid");return n(),p("div",null,[a[2]||(a[2]=E('<h1 id="德摩根与对偶" tabindex="-1">德摩根与对偶 <a class="header-anchor" href="#德摩根与对偶" aria-label="Permalink to &quot;德摩根与对偶&quot;">​</a></h1><div class="epigraph"><p>把与换成或、把 $0$ 换成 $1$，定理还在；把非推进括号，与或对换——化简常常是在对偶世界里走一遭。</p><footer>—— 据 De Morgan, Formal Logic, 1847；Boole, 1854；Shannon, 1938 整理</footer></div><p>上一课<a href="/cs/boolean-algebra">布尔代数公理</a>已经把 De Morgan 与对偶写进公理清单，当时不把它们当方法展开。本课不重列交换分配，也不从逻辑史另起。缺口是：公理保证能变形，还没有一套<strong>机械地把非推进去、把 SOP 翻成 POS</strong> 的手法。后课最小项需要对偶两套规范式，门级要把与或非收成 NAND。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课指出 \\(1+1=1\\)，异或不是公理原语。表达式里的横线若只停在整式外，电路就是「先算一大块再反相」，延迟和扇出都差。缺口因此不是新公理，而是 De Morgan：</p> \\[\\overline{x\\cdot y}=\\bar x+\\bar y,\\qquad \\overline{x+y}=\\bar x\\cdot\\bar y, \\]<p>以及把所有 \\(0/1\\)、\\(\\cdot/+\\) 对换后定理仍真。对偶不是「意思相反」，是代数自同构式的对称。NAND 万能在组成课才当器件事实；本课只走到：任意式可用与、或、非改写，非可以贴到叶子上。</p><p><span class="marginnote">直觉类比：\\(\\overline{x\\cdot y}=\\bar x+\\bar y\\) 说的是「两人都到齐才放行」的反面就是「至少一人缺席」——非推进一步，与就翻成或；对称地，\\(\\overline{x+y}=\\bar x\\cdot\\bar y\\) 里或翻成与。横线每推进一层括号，门的角色就换一次。</span></p><h3 id="对偶不是取反函数" tabindex="-1">对偶不是取反函数 <a class="header-anchor" href="#对偶不是取反函数" aria-label="Permalink to &quot;对偶不是取反函数&quot;">​</a></h3><p>\\(f\\) 的对偶 \\(f^D\\) 由对换与或零幺得到，一般 <strong>不等于</strong> \\(\\bar f\\)。\\(\\bar f\\) 才是补函数。把两件事叫成一个词，后课 POS 会写错。</p><p><span class="marginnote">常见误区：初学者容易把「对偶」当成「取反」。取反（补函数 \\(\\bar f\\)）是把真值表的 0/1 整个颠倒；对偶只是把式子里的与、或、0、1 对调。\\(f^D\\) 与 \\(\\bar f\\) 一般不相等——混淆这两者，后课写 POS 时必错。</span></p><p><span class="marginnote">De Morgan 给出关系代数里的对偶叙述。Shannon 1938 把同一对称用在接点：串联对并联。Harris 用手算把非推到变量上再画两级门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>反复用 De Morgan 与对合 \\(\\overline{\\bar x}=x\\)，直到非只作用在变量上（Nand-of-lits 的前一步）。对偶原理：从已证恒等式对换符号，得到另一条，不必再写真值表。上一课的互补律在对偶下互换。</p>',14)),(n(),l(i,null,{default:o(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20AX%5B%22%E5%85%AC%E7%90%86%EF%BC%9A%E4%B8%8E%E6%88%96%E9%9D%9E%22%5D%20--%3E%20DM%5B%22De%20Morgan%20%E6%8E%A8%E9%9D%9E%22%5D%0A%20%20DM%20--%3E%20LIT%5B%22%E9%9D%9E%E5%8F%AA%E5%9C%A8%E5%8F%B6%E5%AD%90%22%5D%0A%20%20AX%20--%3E%20DUAL%5B%22%E5%AF%B9%E5%81%B6%E6%8D%A2%E4%B8%8E%E6%88%96%22%5D%0A%20%20LIT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%9C%80%E5%B0%8F%E9%A1%B9%E4%B8%8E%E6%9C%80%E5%A4%A7%E9%A1%B9%22%5D%0A%20%20DUAL%20--%3E%20LATER%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("两级与或和两级或与互为对偶实现：1-集合的 SOP 对偶地对应 0-集合的 POS。后课"),e("a",{href:"/cs/minterm-maxterm"},"最小项"),r("会把这一点写成规范展开；本课只保证变形合法。CMOS 的与非、或非比与、或更自然，那是器件课：本课的对偶已经解释「为何成对出现」。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：三变量函数若只在输入 000、011、101 时输出 1，SOP 就写这 3 个最小项之和；对偶地，0-集合有 5 行，POS 要写 5 个最大项之积。真值表 8 行不变，选哪套规范式看哪边行数少、式子短。")],-1)),(n(),l(i,null,{default:o(()=>[s(t,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%9C%9F%E5%80%BC%E8%A1%A8%201-%E9%9B%86%E5%90%88%22%5D%20--%3E%20SOP%5B%22%E8%A7%84%E8%8C%83%20SOP%EF%BC%9A%E6%9C%80%E5%B0%8F%E9%A1%B9%E4%B9%8B%E5%92%8C%22%5D%0A%20%20Z%5B%22%E5%AF%B9%E5%81%B6%E8%A7%86%E8%A7%92%EF%BC%9A0-%E9%9B%86%E5%90%88%22%5D%20--%3E%20POS%5B%22%E8%A7%84%E8%8C%83%20POS%EF%BC%9A%E6%9C%80%E5%A4%A7%E9%A1%B9%E4%B9%8B%E7%A7%AF%22%5D%0A%20%20SOP%20--%3E%20NAND%5B%22NAND%20%E4%B8%A4%E7%BA%A7%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20POS%20--%3E%20NOR%5B%22NOR%20%E4%B8%A4%E7%BA%A7%E5%AE%9E%E7%8E%B0%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入卡诺图，不把多级因式分解当算法。也不把布尔环的 \\(x+x=0\\) 搬进来当 De Morgan 的特例——模 \\(2\\) 加是另一套。集合的德摩根（补集）是<a href="/cs/sets-relations">集合与关系</a>的对照，定义仍以本课代数为准。</p><p>后课默认：非可推到变量；SOP 与 POS 由对偶成对出现；化简在这两套写法上做。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>De Morgan 把非推进括号并交换与或。</li><li>对偶交换 \\(0/1\\) 与与或，定理仍成立；对偶式不是补函数。</li><li>规范最小项 / 最大项是下一课的构造。</li><li>出处：De Morgan, 1847；Boole, 1854；Shannon, 1938。</li></ul>',5))])}const P=A(B,[["render",D]]);export{g as __pageData,P as default};
